            ["Keep at it!"] = "human-male\\npc_combatMid_1.ogg",
            ["Good hit!"] = "human-male\\npc_combatMid_2.ogg",
            ["Watch your back!"] = "human-male\\npc_combatMid_3.ogg",
            ["That's it, that's it!"] = "human-male\\npc_combatMid_4.ogg",
            ["You've got it on the run!"] = "human-male\\npc_combatMid_5.ogg",
            ["Don't let up!"] = "human-male\\npc_combatMid_6.ogg",
            ["Ha! Did you see that?"] = "human-male\\npc_combatMid_7.ogg",
            ["Nearly there!"] = "human-male\\npc_combatMid_8.ogg",
            ["Hit it again!"] = "human-male\\npc_combatMid_9.ogg",
            ["It's on its last legs!"] = "human-male\\npc_combatMid_10.ogg",
            ["Mind your footing!"] = "human-male\\npc_combatMid_11.ogg",
            ["That one's going to leave a mark!"] = "human-male\\npc_combatMid_12.ogg",
            ["Go on! Go on!"] = "human-male\\npc_combatMid_13.ogg",
            ["You make this look like a dance!"] = "human-male\\npc_combatMid_14.ogg",
            ["Swing that blade! Go on!"] = "human-male\\npc_combatMid_15.ogg",
            ["Into the thick of it! That's the way!"] = "human-male\\npc_combatMid_16.ogg",
            ["The Light's with you! Now hit it!"] = "human-male\\npc_combatMid_17.ogg",
            ["Let your pet have a go!"] = "human-male\\npc_combatMid_18.ogg",
            ["Nice shot! Right on target!"] = "human-male\\npc_combatMid_19.ogg",
            ["Where'd you go? Oh! There you are! Stab it!"] = "human-male\\npc_combatMid_20.ogg",
            ["Patch yourself up, then smite it!"] = "human-male\\npc_combatMid_21.ogg",
            ["Call the storm down on it!"] = "human-male\\npc_combatMid_22.ogg",
            ["Burn it! Burn it all! Well, just that one."] = "human-male\\npc_combatMid_23.ogg",
            ["Whatever that green fire is, keep doing it!"] = "human-male\\npc_combatMid_24.ogg",
            ["Turn into something big and scary!"] = "human-male\\npc_combatMid_25.ogg",
            ["Look out!"] = "human-male\\npc_combatStart_1.ogg",
            ["Here they come!"] = "human-male\\npc_combatStart_2.ogg",
            ["Give them what for!"] = "human-male\\npc_combatStart_3.ogg",
            ["Stay sharp!"] = "human-male\\npc_combatStart_4.ogg",
            ["On your guard!"] = "human-male\\npc_combatStart_5.ogg",
            ["Here we go again!"] = "human-male\\npc_combatStart_6.ogg",
            ["Watch it, it's coming right at you!"] = "human-male\\npc_combatStart_7.ogg",
            ["Show them what you've got!"] = "human-male\\npc_combatStart_8.ogg",
            ["Chin up. It'll be all right."] = "human-male\\npc_comforted_1.ogg",
            ["I'm here if you need me."] = "human-male\\npc_comforted_2.ogg",
            ["Thank you. I needed that."] = "human-male\\npc_comforted_3.ogg",
            ["Ha! All right, I'll dance."] = "human-male\\npc_danceAlong_1.ogg",
            ["I haven't danced in ages!"] = "human-male\\npc_danceAlong_2.ogg",
            ["Well, if you insist!"] = "human-male\\npc_danceAlong_3.ogg",
            ["Watch my feet. Or don't."] = "human-male\\npc_danceAlong_4.ogg",
            ["Easy now. Let's get you back on your feet."] = "human-male\\npc_died_1.ogg",
            ["That looked like it hurt."] = "human-male\\npc_died_2.ogg",
            ["Don't worry. Happens to the best of us."] = "human-male\\npc_died_3.ogg",
            ["We'll come back stronger."] = "human-male\\npc_died_4.ogg",
            ["Oh, that's not good."] = "human-male\\npc_died_5.ogg",
            ["Well. That could have gone better."] = "human-male\\npc_died_6.ogg",
            ["Let's agree that one didn't count."] = "human-male\\npc_died_7.ogg",
            ["Lie still. I'll keep watch."] = "human-male\\npc_died_8.ogg",
            ["Keep close in here."] = "human-male\\npc_dungeon_1.ogg",
            ["I don't like the look of this place."] = "human-male\\npc_dungeon_2.ogg",
            ["Watch your step. And your back."] = "human-male\\npc_dungeon_3.ogg",
            ["It's dark in here. I don't love the dark."] = "human-male\\npc_dungeon_4.ogg",
            ["Stay together. Nobody wander off."] = "human-male\\npc_dungeon_5.ogg",
            ["Very impressive."] = "human-male\\npc_flexBack_1.ogg",
            ["Don't hurt yourself."] = "human-male\\npc_flexBack_2.ogg",
            ["Put those away before someone gets hurt."] = "human-male\\npc_flexBack_3.ogg",
            ["That looks good on you."] = "human-male\\npc_gear_1.ogg",
            ["New armor? Very sharp."] = "human-male\\npc_gear_2.ogg",
            ["You'll turn heads in that."] = "human-male\\npc_gear_3.ogg",
            ["Shiny! Did you polish that yourself?"] = "human-male\\npc_gear_4.ogg",
            ["That suits you. Very heroic."] = "human-male\\npc_gear_5.ogg",
            ["Now you look the part."] = "human-male\\npc_gear_6.ogg",
            ["Come on, your body's this way."] = "human-male\\npc_ghost_1.ogg",
            ["I'll walk with you. Don't mind the chill."] = "human-male\\npc_ghost_2.ogg",
            ["You look a bit see-through. It's fine. Mostly fine."] = "human-male\\npc_ghost_3.ogg",
            ["Follow the road. I'll be right here."] = "human-male\\npc_ghost_4.ogg",
            ["Is it cold, being a ghost? You look cold."] = "human-male\\npc_ghost_5.ogg",
            ["Need a lift? You came to the right hill."] = "human-male\\lore523_greet_1.ogg",
            ["Lead the way, {name}."] = "human-male\\npc_greet_1.ogg",
            ["Wind's from the south today. Good flying weather."] = "human-male\\lore523_greet_2.ogg",
            ["Glad to come along, {name}!"] = "human-male\\npc_greet_2.ogg",
            ["Where are we off to today?"] = "human-male\\npc_greet_3.ogg",
            ["I told the others I'd be out for a while. Let's make it count."] = "human-male\\npc_greet_4.ogg",
            ["It's good to get away from the counter for once."] = "human-male\\npc_greet_5.ogg",
            ["Ready when you are, {name}."] = "human-male\\npc_greet_6.ogg",
            ["Some fresh air will do me good."] = "human-male\\npc_greet_7.ogg",
            ["Don't walk too fast. I'm not used to all this adventuring."] = "human-male\\npc_greet_8.ogg",
            ["Well met, {name}! Good to see a friendly face."] = "human-male\\npc_greet_9.ogg",
            ["Right behind you. Where to first?"] = "human-male\\npc_greet_10.ogg",
            ["I packed a lunch. Just in case."] = "human-male\\npc_greet_11.ogg",
            ["Off on an adventure! Don't tell my boss."] = "human-male\\npc_greet_12.ogg",
            ["Fresh boots, fresh start. Let's go."] = "human-male\\npc_greet_13.ogg",
            ["I've been looking forward to this all week."] = "human-male\\npc_greet_14.ogg",
            ["More company! Wonderful."] = "human-male\\npc_group_1.ogg",
            ["Strength in numbers."] = "human-male\\npc_group_2.ogg",
            ["New faces! Hello, everyone."] = "human-male\\npc_group_3.ogg",
            ["A whole party. Now it's an adventure."] = "human-male\\npc_group_4.ogg",
            ["A hearthstone. Faster than a gryphon, I'll admit. Barely."] = "human-male\\lore523_hearth_1.ogg",
            ["Home again!"] = "human-male\\npc_hearth_1.ogg",
            ["Off to the inn. My treat. Well, your treat."] = "human-male\\npc_hearth_2.ogg",
            ["Home sweet home."] = "human-male\\npc_hearth_3.ogg",
            ["Back to a warm bed. Finally."] = "human-male\\npc_hearth_4.ogg",
            ["Oh! Well. That's nice."] = "human-male\\npc_hugged_1.ogg",
            ["Aw, thank you."] = "human-male\\npc_hugged_2.ogg",
            ["Oh, you big softie."] = "human-male\\npc_hugged_3.ogg",
            ["Easy, Skyfeather. They're just tourists."] = "human-male\\lore523_idle_1.ogg",
            ["Nice day for it."] = "human-male\\npc_idle_1.ogg",
            ["Somewhere a courier is late, and I will hear about it."] = "human-male\\lore523_idle_2.ogg",
            ["{zone} is lovely this time of year."] = "human-male\\npc_idle_2.ogg",
            ["If you see a storm cloud, don't tell the birds."] = "human-male\\lore523_idle_3.ogg",
            ["Don't mind me. I'm enjoying the company."] = "human-male\\npc_idle_3.ogg",
            ["You know, I don't get out nearly enough."] = "human-male\\npc_idle_4.ogg",
            ["My feet are already sore. In a good way."] = "human-male\\npc_idle_5.ogg",
            ["I wonder how things are back home without me."] = "human-male\\npc_idle_6.ogg",
            ["Every road looks different when you're not working."] = "human-male\\npc_idle_7.ogg",
            ["Have you ever just stopped and listened to the wind?"] = "human-male\\npc_idle_8.ogg",
            ["I could get used to this."] = "human-male\\npc_idle_9.ogg",
            ["Don't tell anyone, but this beats standing in one spot all day."] = "human-male\\npc_idle_10.ogg",
            ["If you need a hand, just say the word."] = "human-male\\npc_idle_11.ogg",
            ["Good company makes the miles shorter."] = "human-male\\npc_idle_12.ogg",
            ["Mind if I stretch? Old bones."] = "human-male\\npc_idle_13.ogg",
            ["Getting late. The stars will be out soon."] = "human-male\\npc_idle_14.ogg",
            ["Quiet night. I like quiet nights."] = "human-male\\npc_idle_15.ogg",
            ["We've been at it for a while. You're tireless, you know that?"] = "human-male\\npc_idle_16.ogg",
            ["I used to wonder what was past the next hill. Now I know: another hill."] = "human-male\\npc_idle_17.ogg",
            ["Do you ever get used to all this walking?"] = "human-male\\npc_idle_18.ogg",
            ["I've heard stories about you, you know. Some of them are even nice."] = "human-male\\npc_idle_19.ogg",
            ["Smell that? Somebody's cooking something good nearby."] = "human-male\\npc_idle_20.ogg",
            ["If anyone asks, I'm on important business."] = "human-male\\npc_idle_21.ogg",
            ["You're easy company. I mean that kindly."] = "human-male\\npc_idle_22.ogg",
            ["I keep thinking I left something on the stove."] = "human-male\\npc_idle_23.ogg",
            ["Look at that sky."] = "human-male\\npc_idle_24.ogg",
            ["Back home they'll never believe where I've been."] = "human-male\\npc_idle_25.ogg",
            ["I should have brought a better pair of boots."] = "human-male\\npc_idle_26.ogg",
            ["Funny how a quiet road can feel like a holiday."] = "human-male\\npc_idle_27.ogg",
            ["Do adventurers ever take a day off? Asking for a friend. The friend is me."] = "human-male\\npc_idle_28.ogg",
            ["I've counted twelve birds since we set out. Thirteen. Never mind."] = "human-male\\npc_idle_29.ogg",
            ["One of these days you'll have to tell me how you got started."] = "human-male\\npc_idle_30.ogg",
            ["You can tell a lot about someone by how they walk. You walk like you mean it."] = "human-male\\npc_idle_31.ogg",
            ["I'm not complaining. I'm just saying my feet have opinions."] = "human-male\\npc_idle_32.ogg",
            ["Sorry, I've had the same tune stuck in my head all day."] = "human-male\\npc_idle_33.ogg",
            ["If we pass a merchant, remind me I need thread."] = "human-male\\npc_idle_34.ogg",
            ["I wonder what the folks back home are gossiping about."] = "human-male\\npc_idle_35.ogg",
            ["Every time I think I've seen it all, you take me somewhere new."] = "human-male\\npc_idle_36.ogg",
            ["It's peaceful out here. Until it isn't."] = "human-male\\npc_idle_37.ogg",
            ["I could do with a cup of something warm."] = "human-male\\npc_idle_38.ogg",
            ["Morning air's the best air."] = "human-male\\npc_idle_39.ogg",
            ["Early start, eh? I approve."] = "human-male\\npc_idle_40.ogg",
            ["The light's going gold. Best time of day."] = "human-male\\npc_idle_41.ogg",
            ["Stars are out. Makes you feel small, doesn't it?"] = "human-male\\npc_idle_42.ogg",
            ["Shouldn't we both be in bed by now?"] = "human-male\\npc_idle_43.ogg",
            ["Long day. Good day, though."] = "human-male\\npc_idle_44.ogg",
            ["Still going? I'll say this for you: you don't quit."] = "human-male\\npc_idle_45.ogg",
            ["Ha! I'll have to remember that one."] = "human-male\\npc_jokeBack_1.ogg",
            ["Oh, that's terrible. Tell it again."] = "human-male\\npc_jokeBack_2.ogg",
            ["I'm stealing that one."] = "human-male\\npc_jokeBack_3.ogg",
            ["Oh my."] = "human-male\\npc_kissed_1.ogg",
            ["Well, I never."] = "human-male\\npc_kissed_2.ogg",
            ["Now you've made me blush."] = "human-male\\npc_kissed_3.ogg",
            ["Not bad. I'd have landed it softer, but not bad."] = "human-male\\lore523_landed_1.ogg",
            ["Safe and sound."] = "human-male\\npc_landed_1.ogg",
            ["Good landing. I'll tell the birds."] = "human-male\\npc_landed_2.ogg",
            ["Solid ground. Feels strange after all that sky."] = "human-male\\npc_landed_3.ogg",
            ["Down we come. Legs still work? Good."] = "human-male\\npc_landed_4.ogg",
            ["That was a fine flight."] = "human-male\\npc_landed_5.ogg",
            ["Ha! Good one."] = "human-male\\npc_laughAlong_1.ogg",
            ["Heh. You're funny."] = "human-male\\npc_laughAlong_2.ogg",
            ["Ha! That laugh of yours is catching."] = "human-male\\npc_laughAlong_3.ogg",
            ["Learning something new? Good for you."] = "human-male\\npc_learned_1.ogg",
            ["Always improving. I admire that."] = "human-male\\npc_learned_2.ogg",
            ["Something new up your sleeve? I'll be watching."] = "human-male\\npc_learned_3.ogg",
            ["The more you know, the better. That's what I always say."] = "human-male\\npc_learned_4.ogg",
            ["Another level! The birds will want to hear about this."] = "human-male\\lore523_levelUp_1.ogg",
            ["Level {level}! Well done, {name}!"] = "human-male\\npc_levelUp_1.ogg",
            ["Look at you, {name}. Level {level} already."] = "human-male\\npc_levelUp_2.ogg",
            ["Level {level}! That calls for a cheer!"] = "human-male\\npc_levelUp_3.ogg",
            ["Level {level}. I've seen a lot of adventurers come and go. You're one of the good ones."] = "human-male\\npc_levelUp_4.ogg",
            ["Ha! Level {level}! Well earned."] = "human-male\\npc_levelUp_5.ogg",
            ["Level {level}. Wait until I tell everyone back home."] = "human-male\\npc_levelUp_6.ogg",
            ["Stronger every day. I can see it."] = "human-male\\npc_levelUp_7.ogg",
            ["Another level! I knew you had it in you."] = "human-male\\npc_levelUp_8.ogg",
            ["Well, look who's moving up in the world."] = "human-male\\npc_levelUp_9.ogg",
            ["Another step up. Mind you don't get a big head."] = "human-male\\npc_levelUp_10.ogg",
            ["{item}! Now that's a find."] = "human-male\\npc_loot_1.ogg",
            ["Well, look at that. {item}."] = "human-male\\npc_loot_2.ogg",
            ["{item}! Lucky day."] = "human-male\\npc_loot_3.ogg",
            ["Ooh, what did you find?"] = "human-male\\npc_loot_4.ogg",
            ["Anything good in there?"] = "human-male\\npc_loot_5.ogg",
            ["Pockets full! Nice."] = "human-male\\npc_loot_6.ogg",
            ["You're hurt! Get out of there!"] = "human-male\\npc_lowHealth_1.ogg",
