            ["An honor."] = "nightelf-male\\npc_bowBack_2.ogg",
            ["The pleasure's mine."] = "nightelf-male\\npc_bowBack_3.ogg",
            ["{friend} is your Buddy now? The more the merrier!"] = "nightelf-male\\npc_buddy_1.ogg",
