            ["Hooray!"] = "nightelf-male\\npc_cheerAlong_1.ogg",
            ["Huzzah!"] = "nightelf-male\\npc_cheerAlong_2.ogg",
            ["Three cheers!"] = "nightelf-male\\npc_cheerAlong_3.ogg",
            ["Who are you calling chicken?"] = "nightelf-male\\npc_chickenBack_1.ogg",
            ["Bawk yourself."] = "nightelf-male\\npc_chickenBack_2.ogg",
            ["I'm brave! I'm just brave quietly."] = "nightelf-male\\npc_chickenBack_3.ogg",
            ["Well fought!"] = "nightelf-male\\npc_combatEnd_1.ogg",
            ["That's how it's done."] = "nightelf-male\\npc_combatEnd_2.ogg",
            ["Everyone in one piece? Good."] = "nightelf-male\\npc_combatEnd_3.ogg",
            ["Ha! They won't try that again."] = "nightelf-male\\npc_combatEnd_4.ogg",
            ["I'll admit, my heart was pounding."] = "nightelf-male\\npc_combatEnd_5.ogg",
            ["Nicely done."] = "nightelf-male\\npc_combatEnd_6.ogg",
            ["Is it over? It's over. Good."] = "nightelf-male\\npc_combatEnd_7.ogg",
            ["Remind me never to make you angry."] = "nightelf-male\\npc_combatEnd_8.ogg",
            ["Not bad at all!"] = "nightelf-male\\npc_combatEnd_9.ogg",
            ["Victory! I'll be telling everyone about that one."] = "nightelf-male\\npc_combatEnd_10.ogg",
            ["Catch your breath. You earned it."] = "nightelf-male\\npc_combatEnd_11.ogg",
            ["And not a scratch on me. Thanks to you."] = "nightelf-male\\npc_combatEnd_12.ogg",
            ["Hold on, it's weakening!"] = "nightelf-male\\npc_combatLong_1.ogg",
            ["Don't give up now!"] = "nightelf-male\\npc_combatLong_2.ogg",
            ["Steady. Steady."] = "nightelf-male\\npc_combatLong_3.ogg",
            ["This one's stubborn. Keep at it!"] = "nightelf-male\\npc_combatLong_4.ogg",
            ["It's tiring! I can see it!"] = "nightelf-male\\npc_combatLong_5.ogg",
            ["Long fight. You've got more in you."] = "nightelf-male\\npc_combatLong_6.ogg",
            ["Keep at it!"] = "nightelf-male\\npc_combatMid_1.ogg",
            ["Good hit!"] = "nightelf-male\\npc_combatMid_2.ogg",
            ["Watch your back!"] = "nightelf-male\\npc_combatMid_3.ogg",
            ["That's it, that's it!"] = "nightelf-male\\npc_combatMid_4.ogg",
