            ["Don't let up!"] = "nightelf-male\\npc_combatMid_6.ogg",
            ["Ha! Did you see that?"] = "nightelf-male\\npc_combatMid_7.ogg",
            ["Nearly there!"] = "nightelf-male\\npc_combatMid_8.ogg",
            ["Hit it again!"] = "nightelf-male\\npc_combatMid_9.ogg",
            ["It's on its last legs!"] = "nightelf-male\\npc_combatMid_10.ogg",
