            ["Stay sharp!"] = "nightelf-male\\npc_combatStart_4.ogg",
            ["On your guard!"] = "nightelf-male\\npc_combatStart_5.ogg",
            ["Here we go again!"] = "nightelf-male\\npc_combatStart_6.ogg",
            ["Watch it, it's coming right at you!"] = "nightelf-male\\npc_combatStart_7.ogg",
            ["Show them what you've got!"] = "nightelf-male\\npc_combatStart_8.ogg",
            ["Chin up. It'll be all right."] = "nightelf-male\\npc_comforted_1.ogg",
            ["I'm here if you need me."] = "nightelf-male\\npc_comforted_2.ogg",
            ["Thank you. I needed that."] = "nightelf-male\\npc_comforted_3.ogg",
            ["Ha! All right, I'll dance."] = "nightelf-male\\npc_danceAlong_1.ogg",
