            ["That looked like it hurt."] = "nightelf-male\\npc_died_2.ogg",
            ["Don't worry. Happens to the best of us."] = "nightelf-male\\npc_died_3.ogg",
            ["We'll come back stronger."] = "nightelf-male\\npc_died_4.ogg",
            ["Oh, that's not good."] = "nightelf-male\\npc_died_5.ogg",
