            ["Keep close in here."] = "nightelf-male\\npc_dungeon_1.ogg",
            ["I don't like the look of this place."] = "nightelf-male\\npc_dungeon_2.ogg",
            ["Watch your step. And your back."] = "nightelf-male\\npc_dungeon_3.ogg",
            ["It's dark in here. I don't love the dark."] = "nightelf-male\\npc_dungeon_4.ogg",
