            ["Very impressive."] = "nightelf-male\\npc_flexBack_1.ogg",
            ["Don't hurt yourself."] = "nightelf-male\\npc_flexBack_2.ogg",
            ["Put those away before someone gets hurt."] = "nightelf-male\\npc_flexBack_3.ogg",
            ["That looks good on you."] = "nightelf-male\\npc_gear_1.ogg",
            ["New armor? Very sharp."] = "nightelf-male\\npc_gear_2.ogg",
            ["You'll turn heads in that."] = "nightelf-male\\npc_gear_3.ogg",
            ["Shiny! Did you polish that yourself?"] = "nightelf-male\\npc_gear_4.ogg",
            ["That suits you. Very heroic."] = "nightelf-male\\npc_gear_5.ogg",
            ["Now you look the part."] = "nightelf-male\\npc_gear_6.ogg",
            ["Come on, your body's this way."] = "nightelf-male\\npc_ghost_1.ogg",
            ["I'll walk with you. Don't mind the chill."] = "nightelf-male\\npc_ghost_2.ogg",
            ["You look a bit see-through. It's fine. Mostly fine."] = "nightelf-male\\npc_ghost_3.ogg",
