            ["Is it cold, being a ghost? You look cold."] = "nightelf-male\\npc_ghost_5.ogg",
            ["Lead the way, {name}."] = "nightelf-male\\npc_greet_1.ogg",
            ["Glad to come along, {name}!"] = "nightelf-male\\npc_greet_2.ogg",
            ["Where are we off to today?"] = "nightelf-male\\npc_greet_3.ogg",
