            ["Some fresh air will do me good."] = "nightelf-male\\npc_greet_7.ogg",
            ["Don't walk too fast. I'm not used to all this adventuring."] = "nightelf-male\\npc_greet_8.ogg",
            ["Well met, {name}! Good to see a friendly face."] = "nightelf-male\\npc_greet_9.ogg",
