            ["A whole party. Now it's an adventure."] = "nightelf-male\\npc_group_4.ogg",
            ["Home again!"] = "nightelf-male\\npc_hearth_1.ogg",
            ["Off to the inn. My treat. Well, your treat."] = "nightelf-male\\npc_hearth_2.ogg",
            ["Home sweet home."] = "nightelf-male\\npc_hearth_3.ogg",
            ["Back to a warm bed. Finally."] = "nightelf-male\\npc_hearth_4.ogg",
