            ["Aw, thank you."] = "nightelf-male\\npc_hugged_2.ogg",
            ["Oh, you big softie."] = "nightelf-male\\npc_hugged_3.ogg",
            ["Nice day for it."] = "nightelf-male\\npc_idle_1.ogg",
            ["{zone} is lovely this time of year."] = "nightelf-male\\npc_idle_2.ogg",
            ["Don't mind me. I'm enjoying the company."] = "nightelf-male\\npc_idle_3.ogg",
            ["You know, I don't get out nearly enough."] = "nightelf-male\\npc_idle_4.ogg",
            ["My feet are already sore. In a good way."] = "nightelf-male\\npc_idle_5.ogg",
