            ["Nicely done."] = "skyborne-male\\npc_combatEnd_6.ogg",
            ["Is it over? It's over. Good."] = "skyborne-male\\npc_combatEnd_7.ogg",
            ["Remind me never to make you angry."] = "skyborne-male\\npc_combatEnd_8.ogg",
            ["Not bad at all!"] = "skyborne-male\\npc_combatEnd_9.ogg",
