            ["Aw, thank you."] = "skyborne-male\\npc_hugged_2.ogg",
            ["Oh, you big softie."] = "skyborne-male\\npc_hugged_3.ogg",
            ["Nice day for it."] = "skyborne-male\\npc_idle_1.ogg",
            ["{zone} is lovely this time of year."] = "skyborne-male\\npc_idle_2.ogg",
            ["Don't mind me. I'm enjoying the company."] = "skyborne-male\\npc_idle_3.ogg",
            ["You know, I don't get out nearly enough."] = "skyborne-male\\npc_idle_4.ogg",
            ["My feet are already sore. In a good way."] = "skyborne-male\\npc_idle_5.ogg",
            ["I wonder how things are back home without me."] = "skyborne-male\\npc_idle_6.ogg",
            ["Every road looks different when you're not working."] = "skyborne-male\\npc_idle_7.ogg",
            ["Have you ever just stopped and listened to the wind?"] = "skyborne-male\\npc_idle_8.ogg",
            ["I could get used to this."] = "skyborne-male\\npc_idle_9.ogg",
            ["Don't tell anyone, but this beats standing in one spot all day."] = "skyborne-male\\npc_idle_10.ogg",
            ["If you need a hand, just say the word."] = "skyborne-male\\npc_idle_11.ogg",
            ["Good company makes the miles shorter."] = "skyborne-male\\npc_idle_12.ogg",
