            ["If anyone asks, I'm on important business."] = "skyborne-male\\npc_idle_21.ogg",
            ["You're easy company. I mean that kindly."] = "skyborne-male\\npc_idle_22.ogg",
            ["I keep thinking I left something on the stove."] = "skyborne-male\\npc_idle_23.ogg",
            ["Look at that sky."] = "skyborne-male\\npc_idle_24.ogg",
            ["Back home they'll never believe where I've been."] = "skyborne-male\\npc_idle_25.ogg",
            ["I should have brought a better pair of boots."] = "skyborne-male\\npc_idle_26.ogg",
            ["Funny how a quiet road can feel like a holiday."] = "skyborne-male\\npc_idle_27.ogg",
            ["Do adventurers ever take a day off? Asking for a friend. The friend is me."] = "skyborne-male\\npc_idle_28.ogg",
            ["I've counted twelve birds since we set out. Thirteen. Never mind."] = "skyborne-male\\npc_idle_29.ogg",
            ["One of these days you'll have to tell me how you got started."] = "skyborne-male\\npc_idle_30.ogg",
            ["You can tell a lot about someone by how they walk. You walk like you mean it."] = "skyborne-male\\npc_idle_31.ogg",
            ["I'm not complaining. I'm just saying my feet have opinions."] = "skyborne-male\\npc_idle_32.ogg",
            ["Sorry, I've had the same tune stuck in my head all day."] = "skyborne-male\\npc_idle_33.ogg",
            ["If we pass a merchant, remind me I need thread."] = "skyborne-male\\npc_idle_34.ogg",
            ["I wonder what the folks back home are gossiping about."] = "skyborne-male\\npc_idle_35.ogg",
            ["Every time I think I've seen it all, you take me somewhere new."] = "skyborne-male\\npc_idle_36.ogg",
            ["It's peaceful out here. Until it isn't."] = "skyborne-male\\npc_idle_37.ogg",
            ["I could do with a cup of something warm."] = "skyborne-male\\npc_idle_38.ogg",
            ["Morning air's the best air."] = "skyborne-male\\npc_idle_39.ogg",
